		const c0z = cz - r + CONFIG.wfc.originLocal[1] >> 3;
		const c1z = cz + r + CONFIG.wfc.originLocal[1] >> 3;
		for (let z = c0z; z <= c1z; z++) for (let x = c0x; x <= c1x; x++) if (geoConstraints) applyConstraintsToChunk(baseWFC, x, z, geoConstraints);
